    blocks.push({
      start: cur.start, end, lastLine, slug: at.slug, numeric: at.numeric,
      trigger: lead ? normalizeLeadIn(lead[1]) : openingWords(stripMarkers(lines[cur.start]).replace(/^- /, '')),
      text: normalizeRuleText(body),
    });
    cur = null;
  };
