  // not a rule, and it neither opens a block nor ends one.
  let fenced = false;
  lines.forEach((line, i) => {
    if (/^\s*```/.test(line)) { fenced = !fenced; if (cur) cur.end = i; return; }
    if (fenced) { if (cur) cur.end = i; return; }
