  const once = unmarkedProse('- **A** - x. (a-rule)\\n- **B** - y. (b-rule)\\n');
  assert.equal(once, '- **A** - x.\\n- **B** - y.\\n');
  assert.equal(unmarkedProse(once), once);
});

